"""Assemble the BR7 evidence report after the serialized protocol completes."""
import json,csv
from pathlib import Path
root=Path(__file__).resolve().parents[2]; evidence=Path(__file__).resolve().parent
old=json.loads((evidence/'analysis/summary.json').read_text())['runs']
new=json.loads((evidence/'new-analysis/summary.json').read_text())['runs']
series=json.loads((evidence/'short-series.json').read_text())
assert len(series)==6 and all(r['is_valid'] for r in series)
final=json.loads((evidence/'final-storage.json').read_text())
oldm=json.loads((evidence/'analysis/per-mode.json').read_text())['modes']
newm=json.loads((evidence/'new-analysis/per-mode.json').read_text())['modes']
byid={r['run_id']:r for r in new}; lines=['# STEP 11D.3-BR7 — Bare-Wine Presentation Regime Switching','']
case='STEP 11D.3-B RESULT: CASE B3 — INCONCLUSIVE'
def section(n,title,text): lines.extend([f'## {n}. {title}','',text,''])
def table(headers,rows): return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(x) for x in row)+' |' for row in rows])
def name(r):
 rid=r['run_id']
 for i in range(1,4):
  if f'baseline-{i:02d}' in rid:return 'BR6 Baseline '+str(i) if r in old else 'BR7 additional Baseline '+str(i)
 for i in range(1,7):
  if f'sample-{i:02d}' in rid:return 'BR7 short '+str(i)
 return 'BR6 smoke' if r in old else 'BR7 smoke'
def headline(r):
 f=r['frame_outcomes'];rate=r['host_rates_per_second'];t=r['timing_stats_ns']['next_drawable']
 return [name(r),f['candidate_acquisitions'],f['presented'],f['zero'],f"{rate['acquisition']:.4f}",f"{rate['displayed_callback']:.4f}",f"{f['zero_percent_of_exact_outcomes']:.4f}%",r['regime_analysis']['overall_label'].replace('HEALTHY','NORMAL'),f"{t['max_ns']/1e6:.4f}"]
def mode_row(m):
 rid=m['run_id'];r=next(r for r in old+new if r['run_id']==rid)
 return [name(r),m['mode'].replace('HEALTHY','NORMAL'),m['frames'],m['exposure_seconds'],f"{m['acquired_cohort_fps']:.4f}" if m['acquired_cohort_fps'] is not None else 'edge',f"{m['displayed_cohort_fps']:.4f}" if m['displayed_cohort_fps'] is not None else 'edge',f"{100*m['zero_fraction']:.4f}%"]
labels=[byid[r['run_id']]['regime_analysis']['overall_label'] for r in series]
counts={label:labels.count(label) for label in ['HEALTHY','PATHOLOGICAL','MIXED']}
section(1,'Executive summary',f"BR6 Baseline 02 is a technically coherent, transitional presentation pathology, not a single-stall artifact. Its final 243-second segment has 28,912 acquired frames and no valid displayed timestamp. The six accepted BR7 short runs classify {counts['HEALTHY']} NORMAL, {counts['PATHOLOGICAL']} PATHOLOGICAL, {counts['MIXED']} MIXED. The revised proxy observes target AppKit state without the old proxy's window activation or drawable-size assignment. That instrumentation correction means these are not exact old-proxy repeats. Majority health cannot establish B2; a reproducible trigger/state dependency remains unresolved.")
section(2,'Final B classification',case+'\n\nB1 requires an independent sustained repeat with an identified or strongly correlated trigger/state. B2 requires explaining the old pathology as an external/invalid condition. The accepted BR6 pathology remains real; its cause is not proven by the proxy side effects or the normal follow-up.')
section(3,'BR6 accepted evidence',table(['Run','Acquire','Display','Zero','Acquire FPS','Display FPS','Zero %','Regime','Worst drawable ms'],[headline(r) for r in old])+'\n\nEach raw run-result, manifest, owned target app/host traces and trace index was inspected and reanalyzed separately. All four retained accepted runs passed identity, Rosetta, exact runtime/proxy/MoltenVK, trace validity, quantitative readiness, PrefixLease POST, and Gate0 PRE/POST. SHA256 identities are in [analysis/summary.json](evidence/br7/analysis/summary.json). No accepted BR6 evidence was retired.')
section(4,'Regime definitions','NORMAL means sustained near-refresh presentation with high valid-time success; PATHOLOGICAL means sustained acquisition/display divergence with many exact zero-time callbacks; MIXED means both sustained regimes occur. Detection requires five consecutive eligible one-second windows, >=15 exact outcomes, >=90% exposure, no ambiguous acquisition, healthy zero share <=10% or pathological >=50%. These thresholds find candidates, not physical causes. Actual rates/success always accompany labels. Transition/edge frames remain separate; most accepted NORMAL runs exceed95% whole-run success. Times are relative to first host acquire, not process start.')
section(5,'BR6 per-second reanalysis','[windows.csv](evidence/br7/analysis/windows.csv) records separate one- and five-second host and app-clock windows for acquisition, submit, present request, callbacks, valid displayed callbacks, zero-time callbacks, callback-return availability witness, dealloc release witness, drawable p50/p99/max and submit p50/p99/max. Counts and observed exposures are retained. App QPC and host Mach clocks are never aligned by assumption. Whole-run headline FPS uses the app-reported duration; window rates use observed bin exposure.\n\nStandalone per-run timelines: [Smoke](evidence/br7/analysis/smoke-timeline.svg), [Baseline01](evidence/br7/analysis/baseline-01-timeline.svg), [Baseline02](evidence/br7/analysis/baseline-02-timeline.svg), [Baseline03](evidence/br7/analysis/baseline-03-timeline.svg). No pooled regime histogram is used.')
section(6,'Transition analysis','BR6 smoke: NORMAL1–13s, PATHOLOGICAL20–29s; transition bracket12–21s. Baseline01: NORMAL1–298s. Baseline03: NORMAL1–299s. Baseline02: NORMAL5–10s, PATHOLOGICAL11–39s, NORMAL43–56s, PATHOLOGICAL56–299s; conservative brackets9–12s,38–44s,55–57s. It did not remain in a static eventual regime from startup. The final pathology persists243s. Initial/mixed gaps do not support a physical transition timestamp. Exact frame/callback timestamps remain in [frames.csv](evidence/br7/analysis/frames.csv) and [zero_bursts.csv](evidence/br7/analysis/zero_bursts.csv); classifier resolution is not converted into false nanosecond causal precision.')
section(7,'Frame-outcome classification',table(['Run','DISPLAYED_VALID_PRESENTED_TIME','CALLBACK_PRESENTED_TIME_ZERO','NO_PRESENT_CALLBACK','UNKNOWN'],[[name(r),r['frame_outcomes']['presented'],r['frame_outcomes']['zero'],r['frame_outcomes']['no_present_callback'],r['frame_outcomes']['ambiguous']] for r in old+new])+'\n\nEvery acquired frame receives one outcome where supported. SUPERSEDED_BEFORE_DISPLAY, SWAPCHAIN_REPLACED, WINDOW_NOT_PRESENTABLE are zero **assigned categories**, not proven absent physical events. Zero callbacks do not imply those causes. Unknown covers conflicting/nonunique/incomplete chains and terminal censoring; NO_PRESENT_CALLBACK needs a successful unique prefix and >=1s valid trace tail. Success/suboptimal acquisition are both acquired outcomes. Failed acquisition attempts are separately counted.')
section(8,'presentedTime-zero investigation','BR6 Baseline02: 32,441/33,990=95.4428% zero-time callbacks, nine bursts, longest frames5048–33990 (28,943 consecutive). Its first callback timestamp is821079824684625 Mach ns. Earlier major burst655–3928 has3,274 frames. Smoke has1,517/2,457=61.742%, six bursts, longest1,050. Baselines01/03 have16/14 zero callbacks, each in two startup/tail bursts.\n\nBoth valid and zero outcomes have coherent acquire→submit/nextDrawable→request→handler→callback→callback-return→dealloc sequences; the distinguishing observed field is raw presentedTime and its displayed flag. Identity reuse and release also occur for zeros; no supersession proof exists. B02 request spacing p50~8.45ms and pathological drawable p50~7.35ms support a sustained fast loop. Per-outcome request spacing, drawable identity/image reuse spacing, bursts, and exact event joins are in [BR6 analysis narrative](evidence/br7/analysis/BR6-analysis-narrative.md) and summary.json. Never substitute callback delivery time for displayed time.')
section(9,'Window/AppKit telemetry design','Target-owned telemetry reads AppKit only on the main queue, on delivered notifications and at1Hz with0.1s tolerance. Exact layer-to-view/window association is required; unknown association stays unknown. It records visible/key/main/occlusion/miniaturized/app active, window frame, screen ID/visibleFrame/refresh/backing scales/intersection, layer bounds/drawable extent/contentsScale/hidden/opaque and all requested presentation flags. Notifications cover app active/resign, window key/main transitions, miniaturize/deminiaturize, occlusion, screen/backing, move/resize/close. Display refresh uses cached public CoreGraphics mode data.\n\nThe early layer_configuration remains before swapchain for the unchanged PE identity gate. First nextDrawable entry schedules distinct layer_presentation_configuration; async sampling may occur during the first call, not necessarily after return. Validator requires matching identity and actual640x360 configuration; legacy BR6 full-schema validation remains. See [telemetry design](evidence/br7/telemetry-design.md), [lifecycle split](evidence/br7/lifecycle-split.md), and [proxy build receipt](evidence/br7/proxy-build.json). Raw geometry, presentation flags, pacing, FIFO, image count and Wine/MVK implementations are never changed by BR7.')
section(10,'Offline tests','Before accepted live graphics: 387 full storage discovery tests PASS;47 observation/parser tests PASS;15 native dispatch tests PASS; native ownership tests PASS; diff check PASS. Coverage includes target ownership, bounded window fields, notifications/timer/main-queue behavior, frame outcomes, burst gaps, mode segmentation, validator split configuration, PrefixLease, smoke authorization. Source/binary build succeeded. Logs: offline-storage-final.log, offline-observation-final.log, dispatch-tests-final.log, ownership-tests-final.log under evidence/br7. System Python3.9 was accidentally selected for one repeat and lacks Path.stat(follow_symlinks); the established Homebrew3.14 rerun passed. No policy change accommodated that interpreter error. No tests or storage certification ran concurrently with live graphics.')
section(11,'Gate 0','Formal FREE>=45GiB and SCOPED<=45GiB were unchanged. Initial admission encountered a cloned-prefix scope overage and expired one-hour cleanup certification; both blocked before graphics and cleaned up. Verified per-file archives retired only superseded failed/probe/build evidence, preserving paths, metadata, sizes, hashes and restoration instructions. All accepted BR6 evidence, including its prior authorization smoke, stayed expanded. Archive receipts under evidence/br7 record335,039,183-byte and3,777,532-byte archives; SHA25658d0776ca6720e7039ce99a16f0a472484868376a212d1f6387ef3c289d5e5fc and001a6d158491b915b290a16982726314c1ba3c0cf8010f2838888877dfd5edbd. Fresh authenticated preflight→PrefixLease storage smoke→finalization passed before graphics.')
for index,row in enumerate(series,1):
 r=byid[row['run_id']]; h=headline(r)
 section(11+index,f'Short run {index}',f"[{row['run_id']}](runs/{row['run_id']}/run-result.json): PASS, valid, quantitative-ready, Gate0 PRE/POST PASS, PrefixLease POST PASS. {h[1]} acquired, {h[2]} valid displayed, {h[3]} zero; {h[4]}/{h[5]} acquired/displayed FPS; zero fraction{h[6]}; worst nextDrawable{h[8]}ms; {h[7]}.\n\nPer-second/five-second segmentation and complete frame outcomes are retained in new-analysis. Fixed screenshot timestamps are qualitative only. "+('The first attempt at this index was rejected for a malformed/interleaved dyld log line; no parser relaxation or quantitative classification was applied.' if index in (3,5) else ''))
section(18,'Regime table',table(['Run','Mode','Frames','Exposure s','Acquire cohort FPS','Display cohort FPS','Zero %'],[mode_row(m) for m in oldm+newm if m['mode']!='TRANSITION_OR_EDGE'])+'\n\nRuns and proxy revisions remain separate. Cohort FPS is final frame outcome count divided by segment exposure, not instantaneous callback-delivery rate. Callback-window rates are in windows.csv; edge/transition cohorts are retained separately in per-mode.json.')
section(19,'Window-state correlation','See [new window-state comparison](evidence/br7/new-analysis/window-state-comparison.md) and JSON. Frame context uses latest prior target-owned sample at callback time, <=2s age. Stale/no prior/unassociated snapshots remain unknown; callbacks can arrive after the frame’s acquire/request and therefore do not identify its trigger state. Key/main/active/visible/occlusion, screen/geometry/scales and flags are summarized per run and sustained mode. BR6 lacks this state telemetry; no retrospective focus/occlusion cause is invented. A state observed only in healthy new runs cannot establish the old pathology’s trigger.')
section(20,'Visual observation correlation','Each accepted short run has bounded5/15/30/45/59s capture attempts, with exact monotonic capture start/end and first target acquire origin in its visual-observations.json.59s allows shutdown margin; missing captures stay documented. Screen capture does not activate/order windows and requires the target PID. These are qualitative samples, not FPS measurements.\n\nDirect user report for accepted BR7 smoke074106-d99e7461: “It was like the previous flickiring window. I know there were lots of colors changing, but the most noticable one was darker white.” This is retrospective whole-smoke context, with no exact observation timestamp supplied. The app deliberately changes pseudorandom full-window RGB clear every frame (bare_vulkan_app.cpp:1479–1481); perceived flicker/colors alone cannot establish frame loss. Source report is preserved in user-observations.json. Screenshot review and timestamp table are retained in visual-review.md.')
section(21,'FIFO/source interpretation','The app requests VK_PRESENT_MODE_FIFO_KHR; no present mode or layer control was changed. MoltenVK1.4.2 enables display synchronization for non-immediate modes and lazily fetches CAMetalDrawable during submit. Its presented handler invokes endPresentation even when raw Metal presentedTime is zero, substitutes an internal runtime timestamp and continues semaphore/image acquisition bookkeeping. The raw zero remains nondisplayed for this experiment. The acquire API is cheap; drawable scarcity primarily blocks the loop inside lazy submit, not vkAcquireNextImage itself. Fast callbacks and resource progress can therefore coexist with~113 requests/s and~5 valid displays/s; FIFO is not an observed one-valid-display-per-acquire throttle in this stack. The trace does not prove mailbox-like supersession, a FIFO implementation defect, or exact drawable-pool reuse.\n\nApple defines presentedTime as onscreen host time; zero means not yet presented or dropped. Callback-return availability witness and dealloc release witness are distinct from pool recycling/GPU completion. Public WineForge nearby sources conditionally post an event then call superclass nextDrawable, with no custom retry/pacing loop;0.6.0.5tag declares Wine11.18 while0.6.0.4 declares11.17. Neither is proven to produce the retained11.17/0.6.0.5 binary. No private API was invoked and no other backend was reopened. See [source semantics and primary links](evidence/br7/source-semantics.md).')
section(22,'Frame-668-like events','BR6 frame668: submit1,009.932625ms, nextDrawable1,009.654125ms, raw presentedTime0. It lies near the first mode transition bracket; the sustained pathology is much longer. BR6 smoke frame879 has nextDrawable1,005.481166ms, submit1,005.743042ms, zero. Stable B02 pathological cohort’s max is28.815ms; stable healthy B02 max20.966ms; the one-second event belongs to transition/edge cohort under these conservative segments. Thus a one-second tail is not the defining sustained mode. New >=900ms equivalent events and >=100ms tails are searched in new-analysis/extreme_stalls.csv and documented in final results; nextDrawable and submit rows for one frame are not two independent stalls.')
section(23,'Per-mode nextDrawable histograms',table(['Run','Mode']+[b['bucket'] for b in oldm[0]['next_drawable_histogram']],[[name(next(r for r in old+new if r['run_id']==m['run_id'])),m['mode'].replace('HEALTHY','NORMAL')]+[b['count'] for b in m['next_drawable_histogram']] for m in oldm+newm if m['mode']!='TRANSITION_OR_EDGE'])+'\n\nExact bucket edges, percentages and accumulated durations are in each analysis/per-mode.json. Transition/edge histograms remain separate there; no pooled histogram drives classification.')
section(24,'Per-mode submit statistics',table(['Run','Mode','n','Mean ms','p50 ms','p99 ms','Max ms'],[[name(next(r for r in old+new if r['run_id']==m['run_id'])),m['mode'].replace('HEALTHY','NORMAL'),m['submit']['count']]+[f"{m['submit'][k]/1e6:.4f}" for k in ['mean_ns','p50_ns','p99_ns','max_ns']] for m in oldm+newm if m['mode']!='TRANSITION_OR_EDGE'])+'\n\nThese are target native-boundary submits; app wrappers are separately retained. Submit contains lazy drawable acquisition. Histograms and other quantiles are in per-mode.json.')
section(25,'Per-mode phase analysis',table(['Run','Mode','Measured mode period ms','Valid intervals','Q1%','Q2%','Q3%','Q4%'],[[name(next(r for r in old+new if r['run_id']==m['run_id'])),m['mode'].replace('HEALTHY','NORMAL'),f"{m['measured_mode_refresh_period_ns']/1e6:.6f}" if m['measured_mode_refresh_period_ns'] else 'unavailable',m['measured_mode_refresh_samples']]+[f'{q:.2f}' if q is not None else 'unavailable' for q in m['request_phase_quartiles_percent']] for m in oldm+newm if m['mode']!='TRANSITION_OR_EDGE'])+'\n\nMode periods use14–19ms adjacent valid displayed intervals within that cohort. Request quartiles use the run-wide valid-display phase reference for the same observed display, but mode requests are separated. A zero-display mode cannot supply its own refresh measurement. Baseline02 pathological requests are approximately uniform (25.52/23.85/26.91/23.72%); its healthy requests strongly favorQ1 (99.63%). Smoke pathology is not uniformly phased, so the uniformity claim is not universal. Absolute quartiles depend on phase origin/fitted period; BR6 report’s pooled fits are not reused blindly.')
section(26,'Any 300-second confirmation / additional reproduction','Read [additional-run.json](evidence/br7/additional-run.json) and its run-result. If all six short runs are NORMAL, the required additional attempt uses the unchanged baseline2 command and300s duration, matching BR6 Baseline02’s launch/prefix/template/window order more closely and avoiding periodic sample screenshots. It still uses the revised observational proxy and cannot reproduce prohibited old activation/size writes. Environment comparison and hashes are in launch-comparison.json. A normal300s attempt is not a pathological-mode confirmation and does not establishB2. No pathology is intentionally induced. Final measured outcome is in the regime/outcome tables above.')
section(27,'Comparison to Native A','A3 Native Baselines02/03: ~60.01 acquired/~59.99–60.00 displayed FPS, four zero frames each, drawable medians16.06/16.05ms, maxima22.56/36.11ms. Native Baseline01:18,543 acquired/17,072 displayed/1,471 zero,61.81/56.90FPS and1,008.51ms maximum. Its report attributed startup drops to focus/occlusion, but its state fields do not establish that cause; the counts/tails remain observations. Bare Wine healthy cadence is similar; BR6’s long nearly-all-zero segment is more extreme. Native A’s one-second tail means that extreme waits are not uniquely demonstrated to belong to Bare Wine pathology. See A3 report and source-semantics.md.')
section(28,'Comparison to D2','D2 directly sampled WineMetalLayer→CAMetalLayer→drawable semaphore wait inside synchronous source vkQueueSubmit2, delaying READY publication/Metal dispatch and holding the paired history slot. Its exact-R5 low/high runs (~45/~59 WSI/s) and1.175889s tail support that proximal mechanism. BR6 frame668 locates a similar long drawable wait inside submit without DXVK/bridge/history slots. This makes the Wine/Vulkan/window path plausibly relevant, but BR6’s fast-acquire/zero-display regime is not proved to be D2’s~45WSI/s mechanism or root cause. No C or backend experiment was started.')
section(29,'Independent reviewer','A separately spawned GPT-6 Luna with max reasoning performed read-only independent review of segmentation, conservative frame outcomes, window-state correlation, FIFO interpretation, BR6 Baseline02 technical validity, reproduction and final B classification. Root independently checked the relevant source/traces. Reviewer output: [independent-review.md](evidence/br7/independent-review.md); final review follows complete evidence. No consultant/runtime failure was substituted with fabricated approval. The configured model/effort are dispatch metadata, not invented provider introspection.')
section(30,'Final storage',f"Final Gate0 **{final['gate0_status']}**: free{final['free_gib']:.3f}GiB, scoped allocated/inode-deduplicated{final['scoped_fgmetal_gib']:.3f}GiB. Active prefixes:{len(final['active_prefix_leases'])}; uncertified prefixes:{len(final['uncertified_prefixes'])}. Full result: [final-storage.json](evidence/br7/final-storage.json). Conservative attestation inventory bounds can differ from actual mounted/inode usage; neither replaces the formal live measurements.")
section(31,'git diff --check','Final git diff --check status and report/artifact whitespace checks are retained in diff-check.log. Unrelated existing worktree changes were preserved; no commit/push was requested or performed.')
section(32,'Remaining blockers','BR6 lacks direct target window/AppKit state, the old tracer mutated startup window/size state, and exact WineForge source-to-binary provenance is incomplete. A normal new series does not determine whether the old pathology depended on focus/occlusion, instrumentation timing, or another compositor state. Superseded/window-not-presentable causal outcomes cannot be inferred from zero-time callbacks. The one-second successful-drawable timeout edge remains unexplained.')
section(33,'Exact next step','Stop withB3. A separately authorized BR8 should isolate target focus/occlusion/app activity one variable at a time under the frozen passive proxy, correlate exact notifications with transitions, and require an independent300s pathological repeat. First obtain exact retained WineForge build/source provenance if available. Do not change FIFO/image count/layer settings/pacing. STEP11D.3-C remains gated and is not started automatically.')
section(34,'Backend-strategy boundary','DXVK-MacOS remains RESEARCH/REFERENCE through STEP11 and STEP11E. AfterSTEP11E, STOP for the BACKEND STRATEGY GATE before major RIFE/model/product integration. DXMT, D3DMetal/GPTK, RIFE and shipping-backend selection remain closed.')
